#include <bits/stdc++.h>
using namespace std;
struct Term{array<int,4>e;double q;};struct Box{array<double,3>l,u;double ub;};struct Cmp{bool operator()(Box const&a,Box const&b)const{return a.ub<b.ub;}};
static const Term T[]={
{{{2,2,0,0}},0.1674220396877376},{{{2,0,2,0}},0.2048211315254686},{{{1,2,1,0}},0.46668359798666154},{{{1,1,1,1}},1.4962749829713182},{{{1,0,3,0}},0.27715376888031523},{{{0,2,2,0}},0.31017873806448054},{{{0,2,0,2}},0.6636264500698378},{{{0,1,2,1}},1.4677870923536958},{{{0,0,4,0}},0.0901008965001796},{{{0,0,2,2}},0.7673910520134166}};
static bool derive(const Box&b,array<double,4>&l,array<double,4>&u){for(int i=0;i<3;i++){l[i]=b.l[i];u[i]=b.u[i];}double sl=b.l[0]+b.l[1]+b.l[2],su=b.u[0]+b.u[1]+b.u[2];if(sl>1)return false;l[3]=max(0.0,1-su);u[3]=min(1.0,1-sl);return l[3]<=u[3];}
static double pw(double y,int e){if(e==0)return 1;if(y<=0)return 0;if(e==1)return sqrt(y);if(e==2)return y;if(e==3)return y*sqrt(y);return y*y;}
static double mono(const Term&t,const array<double,4>&l,const array<double,4>&u){double box=1,S=1;for(int i=0;i<4;i++){if(t.e[i])box*=pw(u[i],t.e[i]);else S-=l[i];}double am=1;for(int i=0;i<4;i++)if(t.e[i])am*=pw(max(0.0,S)*(.25*t.e[i]),t.e[i]);return min(box,am);}
static double UB(const Box&b){array<double,4>l,u;if(!derive(b,l,u))return -INFINITY;long double s=0;for(auto&t:T)s+=(long double)t.q*mono(t,l,u);return (double)s;}
int main(int argc,char**argv){double best=0.4478773922106,target=argc>1?atof(argv[1]):1e-5;long long maxn=30000000;Box r{{0,0,0},{1,1,1},0};r.ub=UB(r);priority_queue<Box,vector<Box>,Cmp>pq;pq.push(r);long long n=0;while(!pq.empty()&&n<maxn){auto b=pq.top();pq.pop();if(b.ub<=best+target){cout<<setprecision(17)<<"CERTIFIED nodes "<<n<<" lower "<<best<<" upper "<<b.ub<<" gap "<<b.ub-best<<"\n";return 0;}int k=0;double w=-1;for(int i=0;i<3;i++)if(b.u[i]-b.l[i]>w){w=b.u[i]-b.l[i];k=i;}double m=.5*(b.u[k]+b.l[k]);for(int s=0;s<2;s++){Box q=b;if(!s)q.u[k]=m;else q.l[k]=m;array<double,4>l,u;if(!derive(q,l,u))continue;q.ub=UB(q);if(q.ub>best+target)pq.push(q);}n++;if(n%1000000==0)cerr<<n<<" "<<(pq.empty()?best:pq.top().ub)<<" "<<pq.size()<<"\n";}cout<<"INCOMPLETE "<<n<<" "<<(pq.empty()?best:pq.top().ub)<<"\n";return 1;}
